import socket, struct, random

def q(server, port, name, qtype):
    tid=random.randint(0,0xffff)
    pkt=struct.pack(">HHHHHH",tid,0x0100,1,0,0,0)
    pkt+=b"".join(bytes([len(x)])+x.encode() for x in name.split("."))+b"\x00"
    pkt+=struct.pack(">HH",qtype,1)
    s=socket.socket(socket.AF_INET,socket.SOCK_DGRAM); s.settimeout(1.0)
    try:
        s.sendto(pkt,(server,port)); d,_=s.recvfrom(4096)
        return struct.unpack(">H",d[6:8])[0], d[3]&0xf
    except Exception as e:
        return None, repr(e)
    finally: s.close()

# AAAA queries for prices.internal via 127.0.0.11
for name in ["prices.internal"]:
    for qt in [1,28,255]:
        an, rc = q("127.0.0.11", 53, name, qt)
        print(f"{name} qtype={qt}: an={an} rc={rc}")
EOF"}

